        function solvePuzzle() {
            const table = document.querySelector('table');
            const rows = table.rows;

            // Extract the smaller numbers from each cell
            const numbers = [];
            for (let i = 0; i < rows.length; i++) {
                for (let j = 0; j < rows[i].cells.length; j++) {
                    numbers.push(rows[i].cells[j].textContent);
                }
            }

            // Reorganize the numbers into pairs
            const pairs = [];
            for (let i = 0; i < numbers.length; i += 2) {
                pairs.push([numbers[i], numbers[i + 1]]);
            }

            // Calculate the sum of each pair
            const sums = pairs.map((pair) => pair[0] + pair[1]);

            // Find the missing pair
            const missingPair = sums.findIndex((sum) => sum !== 9);
            if (missingPair === -1) {
