<html>
  <head>
    <title>Image with Caption</title>
    <style>
      #img-container {
        text-align: center;
      }
      #img-container img {
        max-width: 100%;
        height: auto;
      }
      #img-container p {
        margin: 0;
        font-style: italic;
      }
    </style>
