Here's a C++ program that generates the Fibonacci sequence using a recursive function. It prompts the user to input the first two integers and the number of sequence elements to generate. It also includes error handling for invalid inputs.

```cpp
#include <iostream>
#include <string>
#include <stdexcept>

using namespace std;

int fibonacci(int n, int a, int b) {
    if (n == 0) {
        return a;
    } else if (n == 1) {
        return b;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

int main() {
    int first_num, second_num, num_elements;
    string input;

    cout << "Enter the first two integers: ";
    getline(cin, input);

    istringstream iss(input);
    iss >> first_num >> second_num;

    if (!iss || first_num < 0 || second_num < 0) {
        throw runtime_error("Invalid input. Please enter non-negative integers.");
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> num_elements;

    if (num_elements <= 0) {
        throw runtime_error("Invalid input. Please enter a positive integer.");
    }

    int sequence[num_elements];
    sequence[0] = first_num;
    sequence[1] = second_num;

    for (int i = 2; i < num_elements; i++) {
        sequence[i] = fibonacci(i, second_num, first_num + second_num);
    }

    cout << "Fibonacci sequence: ";
    for (int i = 0; i < num_elements; i++) {
        cout << sequence[i] << ", ";
    }
    cout << endl;

    return 0;
}
```

