Here's a simple MATLAB code to identify the tense of a given sentence:

```matlab
function tense = identify_tense(sentence)
    % Split the sentence into words
    words = split(sentence);

    % Identify the verbs
    verbs = [];
    for i = 1:numel(words)
        if ismember(words{i}, {'be', 'have', 'do', 'go', 'see', 'hear', 'eat', 'drink'}) || strcmp(words{i}, 'will') || strcmp(words{i}, 'would') || strcmp(words{i}, 'can') || strcmp(words{i}, 'could') || strcmp(words{i}, 'may') || strcmp(words{i}, 'might') || strcmp(words{i}, 'must') || strcmp(words{i}, 'ought') || strcmp(words{i}, 'shall') || strcmp(words{i}, 'should') || strcmp(words{i}, 'will') || strcmp(words{i}, 'would')
            verbs = [verbs, words{i}];
        end
    end

    % Check for present conditional tense
    if isempty(verbs) || ~ismember('will', verbs) || ~ismember('would', verbs)
        tense = 'present';
    else
        tense = 'present conditional';
    end
end

% Test the function with the given sentence
