  { name: 'green apple', position: 9, randomize: false }
];

const result = [];

fruits.forEach(fruit => {
  if (fruit.randomize) {
    const randomIndex = Math.floor(Math.random() * result.length);
    result.splice(randomIndex, 0, fruit);
  } else {
    result.push(fruits[fruit.position - 1]);
  }
});

console.log(result);
