    die("Connection failed: " . $conn->connect_error);
}

// Get current work session data from the database
$sql = "SELECT * FROM work_sessions WHERE start_time >= CURRENT_TIMESTAMP() AND end_time > CURRENT_TIMESTAMP() ORDER BY start_time DESC LIMIT 1";
$result = $conn->query($sql);

if ($result->num_rows > 0) {
    // Get the start time of the current work session
    $start_time = $result->fetch_assoc()["start_time"];

    // Calculate the elapsed time since the start time
    $elapsed_time = time() - strtotime($start_time);

