To create a simple toast notification using React Context, follow these steps:

1. Create a new file named `ToastContext.js` and define the context:
```javascript
import React from 'react';

const ToastContext = React.createContext();

function ToastProvider({ children }) {
  const [toast, setToast] = React.useState(null);

  function showToast(message) {
    setToast({ message, visible: true });
    setTimeout(() => {
      setToast({ message, visible: false });
    }, 3000);
  }

  return (
    <ToastContext.Provider value={{ showToast }}>
      {children}
    </ToastContext.Provider>
  );
}

export { ToastContext, ToastProvider };
```
2. In your main application file, import the `ToastContext` and wrap your app in the `ToastProvider`:
```javascript
import React from 'react';
import { ToastContext, ToastProvider } from './ToastContext';

function App() {
  return (
    <ToastProvider>
      {/* Your app content goes here */}
    </ToastProvider>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
```
3. Now, you can use the `showToast` function from anywhere within your app by wrapping it in the `ToastContext.Consumer`. For example:
```javascript
import React from 'react';
import { ToastContext, ToastProvider } from './ToastContext';

function MyComponent() {
  return (
    <ToastContext.Consumer>
      {({ showToast }) => (
        <button onClick={() => showToast('This is a toast!')}>Show Toast</button>
      )}
    </ToastContext.Consumer>
  );
}

export default MyComponent;
```
When you click the button, a toast notification will be displayed for 3 seconds.

