```go
package main

import (
	"fmt"
	"strings"
)

var negativeWords = []string{"not", "never", "no", "none", "nothing"}

func hasDoubleNegative(sentence string) bool {
	words := strings.Split(sentence, " ")
	for _, word := range words {
		if containsNegativeWord(word) && hasNotFollowedByNegativeWord(word, words) {
			return true
		}
	}
	return false
}

func containsNegativeWord(word string) bool {
	for _, w := range negativeWords {
		if w == word {
			return true
		}
	}
	return false
}

func hasNotFollowedByNegativeWord(word string, words []string) bool {
	for i := 0; i < len(words); i++ {
		if words[i] == "not" && words[i+1] == word {
			return false
		}
	}
	return true
}

func main() {
	sentence := "He isn't not worried about the coronavirus situation"
	if hasDoubleNegative(sentence) {
		fmt.Println("The sentence contains a double negative.")
	} else {
		fmt.Println("The sentence does not contain a double negative.")
	}
}
```

This code defines two functions: `hasDoubleNegative` and `containsNegativeWord`. The `hasDoubleNegative` function checks if a sentence contains a double negative by iterating through each word in the sentence and checking if it is a negative word and if it is not followed by another negative word. The `containsNegativeWord` function checks if a word is a negative word by comparing it to the list of negative words defined in the `negativeWords` variable.

